      lon=locationManager.getLastKnownLocation(LocationManager.GPS_PROVIDER).getLongitude();
    }
    else if (locationManager.getLastKnownLocation(LocationManager.NETWORK_PROVIDER) != null) {
      Log.d("TAG","Inside NETWORK");
